theFix.after:
export function isNewCheckoutEnabled(): boolean {
  const value = process.env.ENABLE_NEW_CHECKOUT;
  if (value === undefined) {
    console.warn('ENABLE_NEW_CHECKOUT is not set in this environment — defaulting to disabled');
  }
  return value === 'true';
}
